definition.script:
pipeline {
    agent any
    environment {
        // Contenedor temporal de MariaDB, uno por ejecución
        BD_CONTENEDOR = "bd-ci-${BUILD_NUMBER}"
        BD_NOMBRE = 'dbgestor'
    }
    stages {
        stage('Checkout') {
            steps {
                // Descarga el código del repositorio (el script de la BD está en db/)
                git branch: 'main', url: 'https://github.com/Diegue83/microserviciobackend.git'
            }
        }
        stage('Ver Directorio') {
            steps {
                sh 'ls -la db'
                sh 'docker version --format "Docker {{.Server.Version}}"'
            }
        }
        stage('Validar script en MariaDB') {
            steps {
                sh '''
                    mkdir -p reportes
                    docker rm -f "$BD_CONTENEDOR" 2>/dev/null || true

                    docker run -d --name "$BD_CONTENEDOR" \
                      -e MARIADB_ROOT_PASSWORD=ci \
                      -e MARIADB_DATABASE="$BD_NOMBRE" \
                      -v "${WORKSPACE}/db":/docker-entrypoint-initdb.d:ro \
                      mariadb:11.4

                    # Espera a que termine de cargar el script y arranque el servidor final
                    for i in $(seq 1 60); do
                      if docker logs "$BD_CONTENEDOR" 2>&1 | grep -q "init process done" \
                         && docker exec "$BD_CONTENEDOR" healthcheck.sh --connect --innodb_initialized >/dev/null 2>&1; then
                        break
                      fi
                      sleep 3
                    done

                    TABLAS=$(docker exec "$BD_CONTENEDOR" mariadb -uroot -pci -N -e \
                      "SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='$BD_NOMBRE'")
                    echo "Tablas creadas: $TABLAS"
                    if [ "$TABLAS" != "6" ]; then
                      docker logs "$BD_CONTENEDOR" > reportes/mariadb.log 2>&1
                      echo "ERROR: se esperaban 6 tablas"
                      exit 1
                    fi
                '''
            }
        }
        stage('Análisis del esquema') {
            steps {
                sh '''
                    # Esquema limpio (sin datos ni comentarios propios de mysqldump) para el análisis estático
                    docker exec "$BD_CONTENEDOR" sh -c \
                      "mariadb-dump -uroot -pci --no-data --compact --skip-comments $BD_NOMBRE | grep -vE '^/[*](!|M!)'" \
                      > reportes/esquema.sql

                    docker exec -i "$BD_CONTENEDOR" mariadb -uroot -pci -t "$BD_NOMBRE" > reportes/analisis-esquema.txt <<'SQL'
SELECT '== Tablas' AS '';
SELECT table_name AS tabla, engine AS motor, table_collation AS cotejamiento, table_rows AS filas
  FROM information_schema.tables WHERE table_schema = DATABASE() ORDER BY 1;
SELECT '== Tablas sin llave primaria' AS '';
SELECT t.table_name AS tabla
  FROM information_schema.tables t
  LEFT JOIN information_schema.table_constraints c
    ON c.table_schema = t.table_schema AND c.table_name = t.table_name AND c.constraint_type = 'PRIMARY KEY'
 WHERE t.table_schema = DATABASE() AND c.constraint_name IS NULL;
SELECT '== Llaves foraneas declaradas' AS '';
SELECT COUNT(*) AS total FROM information_schema.referential_constraints WHERE constraint_schema = DATABASE();
SELECT '== Indices *FK sin restriccion FOREIGN KEY' AS '';
SELECT DISTINCT s.table_name AS tabla, s.index_name AS indice, s.column_name AS columna
  FROM information_schema.statistics s
  LEFT JOIN information_schema.key_column_usage k
    ON k.table_schema = s.table_schema AND k.table_name = s.table_name
   AND k.column_name = s.column_name AND k.referenced_table_name IS NOT NULL
 WHERE s.table_schema = DATABASE() AND s.index_name LIKE '%FK' AND k.constraint_name IS NULL;
SELECT '== Columnas de contrasena' AS '';
SELECT table_name AS tabla, column_name AS columna, column_type AS tipo
  FROM information_schema.columns WHERE table_schema = DATABASE() AND column_name REGEXP 'contra|pass';
SELECT '== Tablas con charset distinto de utf8mb4' AS '';
SELECT table_name AS tabla, table_collation AS cotejamiento
  FROM information_schema.tables WHERE table_schema = DATABASE() AND table_collation NOT LIKE 'utf8mb4%';
SQL
                    cat reportes/analisis-esquema.txt
                '''
            }
        }
        stage('Calidad SQL - SQLFluff') {
            steps {
                sh '''
                    docker run --rm \
                      -v "${WORKSPACE}":/src \
                      -w /src \
                      sqlfluff/sqlfluff:3.4.2 \
                      lint reportes/esquema.sql --dialect mariadb --format json \
                      > reportes/sqlfluff.json || true

                    docker run --rm \
                      -v "${WORKSPACE}":/src \
                      -w /src \
                      sqlfluff/sqlfluff:3.4.2 \
                      lint reportes/esquema.sql --dialect mariadb \
                      > reportes/sqlfluff.txt || true
                    tail -5 reportes/sqlfluff.txt

                    # Los avisos de estilo no detienen el pipeline; un esquema que no se puede analizar sí
                    if grep -q '"code": "PRS"' reportes/sqlfluff.json; then
                      echo "ERROR: SQLFluff no pudo analizar el esquema"
                      exit 1
                    fi
                '''
            }
        }
        stage('Security Scan (SAST) - Semgrep') {
            steps {
                sh '''
                    docker run --rm \
                      --network bridge \
                      -v "${WORKSPACE}":/src \
                      -w /src \
                      semgrep/semgrep \
                      semgrep scan \
                        --config=auto \
                        --json \
                        --output=reportes/semgrep.json \
                        db
                '''
            }
        }
    }
    post {
        always {
            sh 'docker rm -f "$BD_CONTENEDOR" 2>/dev/null || true'
            archiveArtifacts artifacts: 'reportes/*',
                allowEmptyArchive: true,
                fingerprint: true
        }
    }
}
